TEST(EditableSchemaDocument, RetainsMixedRawAndTaggedUnionSourceOwnership) {
    auto const document{TemporarySchema{}.load()};
    auto const raw{declaration_id(document, "authored_unions", "ExistingUnion", "authored")};
    auto const tagged{declaration_id(document, "authored_unions", "ExistingTagged", "authored")};
    auto declaration_text = [&](DeclarationId const id) {
        auto const declaration{document.declarations().find(id)};
        EXPECT_TRUE(declaration.has_value());
        EXPECT_TRUE(declaration.has_value() &&
                    document.declarations()
                        .source[document.declarations().index(*declaration)]
                        .has_value());
        if (!declaration.has_value() || !document.declarations()
                                             .source[document.declarations().index(*declaration)]
                                             .has_value()) {
            return std::string_view{};
        }
        auto const& range{
            *document.declarations().source[document.declarations().index(*declaration)]};
        auto const& source{document.storage().sources.text(document.source_span(range).file)};
        return std::string_view{source}.substr(document.source_span(range).offset,
                                               document.source_span(range).end_offset -
                                                   document.source_span(range).offset);
    };

    EXPECT_TRUE(declaration_text(raw).starts_with("(union ExistingUnion"));
    EXPECT_TRUE(declaration_text(tagged).starts_with("(tagged-union ExistingTagged"));
    auto const type{
        lispb::codegen::find_test_type(document.types(), "authored_unions", "ExistingTagged")};
    ASSERT_TRUE(type.has_value());
    EXPECT_TRUE(((document.types().definition(*type)).kind() ==
                 lispb::schema::TypeDefinitionKind::tagged_union));
}

