    ASSERT_TRUE(
        document.declarations().source[document.declarations().index(*declaration)].has_value());
    auto const& range{*document.declarations().source[document.declarations().index(*declaration)]};
    auto const& source{document.storage().sources.text(document.source_span(range).file)};
    auto const declaration_text{std::string_view{source}.substr(
        document.source_span(range).offset,
        document.source_span(range).end_offset - document.source_span(range).offset)};
    EXPECT_TRUE(declaration_text.starts_with("(mini-float ExistingMiniFloat"));

    auto const type{document.types().find(
        document.declarations().identity[document.declarations().index(*declaration)])};
    ASSERT_TRUE(type.has_value());
    auto const& resolved{document.types().definition(*type)};
    EXPECT_EQ(
        document.types()
            .definitions()
            .mini_floats.sign_bits[document.types().definitions().mini_floats.index(resolved)],
        1U);
