TEST(EditableSchemaDocument, PreservesRecordMembersAndCommentsForStructuralEdits) {
    TemporarySchema files;
    auto document{files.load()};
    auto const record{declaration_id(document, "authored_records", "ExistingRecord", "authored")};
    auto replacement{document.storage().declarations.records.clone(
        *document.declaration_handle(record, lispb::codegen::DeclarationKind::record))};
    document.storage()
        .declarations.records
        .export_specifier[document.storage().declarations.records.index(replacement)] =
        document.storage().strings.intern("RECORD_API");
    auto value{
        document.storage().declarations.record_members.clone(document.storage().declarations.items(
            document.storage()
                .declarations.records
                .members[document.storage().declarations.records.index(replacement)])[0])};
    auto flag{document.storage().declarations.items(
        document.storage()
            .declarations.records
            .members[document.storage().declarations.records.index(replacement)])[1]};
    document.storage()
        .declarations.record_members
        .type[document.storage().declarations.record_members.index(value)] = [&] {
        auto row_0{document.storage().declarations.type_refs.clone(
            document.storage()
                .declarations.record_members
                .type[document.storage().declarations.record_members.index(value)])};
        document.storage()
            .declarations.type_refs.name[document.storage().declarations.type_refs.index(row_0)] =
            document.storage().strings.intern("std::uint64_t");
        return row_0;
    }();
    document.storage()
        .declarations.record_members
        .count[document.storage().declarations.record_members.index(value)] = 2;
    auto duplicate{document.storage().declarations.record_members.clone(flag)};
    document.storage()
        .declarations.record_members
        .name[document.storage().declarations.record_members.index(duplicate)] =
        document.storage().strings.intern("flag_copy");
    document.storage()
        .declarations.record_members
        .count[document.storage().declarations.record_members.index(duplicate)] = 3;
    document.storage()
        .declarations.records.members[document.storage().declarations.records.index(replacement)] =
        document.storage().declarations.range<lispb::codegen::RecordMemberId>(
            {flag, duplicate, value});

    auto applied{document.apply(document.replace_declaration(record, std::move(replacement)))};
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    auto preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    auto const& updated{preview->front().updated};
    auto const flag_comment{updated.find("; Keep the flag member note.")};
    auto const flag_position{updated.find("(member flag ")};
    auto const copy_position{updated.find("(member flag_copy ")};
    auto const record_comment{updated.find("; Keep the record note.")};
    auto const value_comment{updated.find("; Keep the value member note.")};
    auto const value_position{updated.find("(member value ")};
    ASSERT_NE(flag_comment, std::string::npos);
    ASSERT_NE(flag_position, std::string::npos);
    ASSERT_NE(copy_position, std::string::npos);
    ASSERT_NE(record_comment, std::string::npos);
    ASSERT_NE(value_comment, std::string::npos);
    ASSERT_NE(value_position, std::string::npos);
    EXPECT_LT(flag_comment, flag_position);
    EXPECT_LT(flag_position, copy_position);
    EXPECT_LT(copy_position, record_comment);
    EXPECT_LT(record_comment, value_comment);
    EXPECT_LT(value_comment, value_position);
    EXPECT_NE(updated.find("(member value   std::uint64_t"), std::string::npos);
    EXPECT_NE(updated.find(":count 2"), std::string::npos);
    EXPECT_NE(updated.find("(member flag_copy std::uint8_t :count 3)"), std::string::npos);
    EXPECT_NE(updated.find("; value member trailing note"), std::string::npos);
    EXPECT_NE(updated.find(":export-specifier RECORD_API"), std::string::npos);

    ASSERT_TRUE(document.undo().value());
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    EXPECT_TRUE(preview->empty());
    ASSERT_TRUE(document.redo().value());

    auto deletion{document.storage().declarations.records.clone(
        *document.declaration_handle(record, lispb::codegen::DeclarationKind::record))};
    document.storage()
        .declarations.records.members[document.storage().declarations.records.index(deletion)] =
        [&] {
            auto const original_items{document.storage().declarations.items(
                document.storage()
                    .declarations.records
                    .members[document.storage().declarations.records.index(deletion)])};
            auto rows{std::vector(original_items.begin(), original_items.end())};
            std::erase_if(rows, [&](auto id) {
                return document.storage().strings.view(
                           document.storage()
                               .declarations.record_members
                               .name[document.storage().declarations.record_members.index(id)]) ==
                       "value";
            });
            return document.storage().declarations.range(rows);
        }();
    applied = document.apply(document.replace_declaration(record, std::move(deletion)));
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    EXPECT_EQ(preview->front().updated.find("(member value "), std::string::npos);
    EXPECT_EQ(preview->front().updated.find("; Keep the record note."), std::string::npos);
    EXPECT_EQ(preview->front().updated.find("; Keep the value member note."), std::string::npos);
    EXPECT_EQ(preview->front().updated.find("; value member trailing note"), std::string::npos);
    EXPECT_NE(preview->front().updated.find("; Keep the flag member note."), std::string::npos);

    ASSERT_TRUE(document.undo().value());
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    EXPECT_NE(preview->front().updated.find("(member value "), std::string::npos);
    ASSERT_TRUE(document.redo().value());

    auto saved{document.save()};
    ASSERT_TRUE(saved.has_value()) << saved.error().message;
    auto reloaded{files.load()};
    auto const reloaded_record{
        declaration_id(reloaded, "authored_records", "ExistingRecord", "authored")};
    auto const schema{
        reloaded.declaration_handle(reloaded_record, lispb::codegen::DeclarationKind::record)};
    ASSERT_TRUE(schema.has_value());
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.records
                      .export_specifier[reloaded.storage().declarations.records.index(*schema)]),
              "RECORD_API");
    ASSERT_EQ(
        reloaded.storage()
            .declarations.records.members[reloaded.storage().declarations.records.index(*schema)]
            .size(),
        2U);
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.record_members
                      .name[reloaded.storage().declarations.record_members.index(
                          reloaded.storage().declarations.items(
                              reloaded.storage().declarations.records.members
                                  [reloaded.storage().declarations.records.index(*schema)])[0])]),
              "flag");
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.record_members
                      .name[reloaded.storage().declarations.record_members.index(
                          reloaded.storage().declarations.items(
                              reloaded.storage().declarations.records.members
                                  [reloaded.storage().declarations.records.index(*schema)])[1])]),
              "flag_copy");
    EXPECT_EQ(
        reloaded.storage()
            .declarations.record_members.count[reloaded.storage().declarations.record_members.index(
                reloaded.storage().declarations.items(
                    reloaded.storage().declarations.records.members
                        [reloaded.storage().declarations.records.index(*schema)])[1])],
        3U);

    auto const module_source{std::ranges::find_if(reloaded.source_files(), [&](auto const& source) {
        return reloaded.storage().sources.filesystem_path(source).filename() == "modules.lispb";
    })};
    ASSERT_NE(module_source, reloaded.source_files().end());
    EXPECT_EQ(reloaded.storage().sources.text(*module_source).find("; Keep the record note."),
              std::string::npos);
    EXPECT_EQ(reloaded.storage().sources.text(*module_source).find("; Keep the value member note."),
              std::string::npos);
    EXPECT_NE(reloaded.storage().sources.text(*module_source).find("; Keep the flag member note."),
              std::string::npos);
}

TEST(EditableSchemaDocument, PreservesRawUnionAlternativesForStructuralEdits) {
    TemporarySchema files;
    auto document{files.load()};
    auto const raw{declaration_id(document, "authored_unions", "ExistingUnion", "authored")};
    auto replacement{document.storage().declarations.unions.clone(
        *document.declaration_handle(raw, lispb::codegen::DeclarationKind::union_type))};
    auto value{document.storage().declarations.union_alternatives.clone(
        document.storage().declarations.items(
            document.storage()
                .declarations.unions
                .alternatives[document.storage().declarations.unions.index(replacement)])[0])};
    auto small{document.storage().declarations.items(
        document.storage()
            .declarations.unions
            .alternatives[document.storage().declarations.unions.index(replacement)])[1]};
    document.storage()
        .declarations.union_alternatives
        .type[document.storage().declarations.union_alternatives.index(value)] = [&] {
        auto row_0{document.storage().declarations.type_refs.clone(
            document.storage()
                .declarations.union_alternatives
                .type[document.storage().declarations.union_alternatives.index(value)])};
        document.storage()
            .declarations.type_refs.name[document.storage().declarations.type_refs.index(row_0)] =
            document.storage().strings.intern("std::uint64_t");
        return row_0;
    }();
    document.storage()
        .declarations.union_alternatives
        .count[document.storage().declarations.union_alternatives.index(value)] = 2;
    auto duplicate{document.storage().declarations.union_alternatives.clone(small)};
    document.storage()
        .declarations.union_alternatives
        .name[document.storage().declarations.union_alternatives.index(duplicate)] =
        document.storage().strings.intern("small_copy");
    document.storage()
        .declarations.union_alternatives
        .count[document.storage().declarations.union_alternatives.index(duplicate)] = 3;
    document.storage()
        .declarations.unions
        .alternatives[document.storage().declarations.unions.index(replacement)] =
        document.storage().declarations.range<lispb::codegen::UnionAlternativeId>(
            {small, duplicate, value});

    auto applied{document.apply(document.replace_declaration(raw, std::move(replacement)))};
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    auto preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    auto const& updated{preview->front().updated};
    auto const small_comment{updated.find("; Keep the small alternative note.")};
    auto const small_position{updated.find("(alternative small ")};
    auto const copy_position{updated.find("(alternative small_copy ")};
    auto const value_comment{updated.find("; Keep the value alternative note.")};
    auto const value_position{updated.find("(alternative value ")};
    ASSERT_NE(small_comment, std::string::npos);
    ASSERT_NE(small_position, std::string::npos);
    ASSERT_NE(copy_position, std::string::npos);
    ASSERT_NE(value_comment, std::string::npos);
    ASSERT_NE(value_position, std::string::npos);
    EXPECT_LT(small_comment, small_position);
    EXPECT_LT(small_position, copy_position);
    EXPECT_LT(copy_position, value_comment);
    EXPECT_LT(value_comment, value_position);
    EXPECT_NE(updated.find("(alternative value   std::uint64_t"), std::string::npos);
    EXPECT_NE(updated.find(":count 2"), std::string::npos);
    EXPECT_NE(updated.find("(alternative small_copy std::uint8_t :count 3)"), std::string::npos);
    EXPECT_NE(updated.find("; value alternative trailing note"), std::string::npos);

    ASSERT_TRUE(document.undo().value());
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    EXPECT_TRUE(preview->empty());
    ASSERT_TRUE(document.redo().value());

    auto saved{document.save()};
    ASSERT_TRUE(saved.has_value()) << saved.error().message;
    auto reloaded{files.load()};
    auto const reloaded_raw{
        declaration_id(reloaded, "authored_unions", "ExistingUnion", "authored")};
    auto const schema{
        reloaded.declaration_handle(reloaded_raw, lispb::codegen::DeclarationKind::union_type)};
    ASSERT_TRUE(schema.has_value());
    ASSERT_EQ(
        reloaded.storage()
            .declarations.unions.alternatives[reloaded.storage().declarations.unions.index(*schema)]
            .size(),
        3U);
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.union_alternatives
                      .name[reloaded.storage().declarations.union_alternatives.index(
                          reloaded.storage().declarations.items(
                              reloaded.storage().declarations.unions.alternatives
                                  [reloaded.storage().declarations.unions.index(*schema)])[0])]),
              "small");
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.union_alternatives
                      .name[reloaded.storage().declarations.union_alternatives.index(
                          reloaded.storage().declarations.items(
                              reloaded.storage().declarations.unions.alternatives
                                  [reloaded.storage().declarations.unions.index(*schema)])[1])]),
              "small_copy");
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.union_alternatives
                      .name[reloaded.storage().declarations.union_alternatives.index(
                          reloaded.storage().declarations.items(
                              reloaded.storage().declarations.unions.alternatives
                                  [reloaded.storage().declarations.unions.index(*schema)])[2])]),
              "value");
    EXPECT_EQ(reloaded.storage()
                  .declarations.union_alternatives
                  .count[reloaded.storage().declarations.union_alternatives.index(
                      reloaded.storage().declarations.items(
                          reloaded.storage().declarations.unions.alternatives
                              [reloaded.storage().declarations.unions.index(*schema)])[1])],
              3U);
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.type_refs.name[reloaded.storage().declarations.type_refs.index(
                          reloaded.storage().declarations.union_alternatives.type
                              [reloaded.storage().declarations.union_alternatives.index(
                                  reloaded.storage().declarations.items(
                                      reloaded.storage().declarations.unions.alternatives
                                          [reloaded.storage().declarations.unions.index(
                                              *schema)])[2])])]),
              "std::uint64_t");
    EXPECT_EQ(reloaded.storage()
                  .declarations.union_alternatives
                  .count[reloaded.storage().declarations.union_alternatives.index(
                      reloaded.storage().declarations.items(
                          reloaded.storage().declarations.unions.alternatives
                              [reloaded.storage().declarations.unions.index(*schema)])[2])],
              2U);
}

TEST(EditableSchemaDocument, PreservesTaggedUnionAlternativesForStructuralEdits) {
    TemporarySchema files;
    auto document{files.load()};
    auto const tagged{declaration_id(document, "authored_unions", "ExistingTagged", "authored")};
    auto replacement{document.storage().declarations.tagged_unions.clone(
        *document.declaration_handle(tagged, lispb::codegen::DeclarationKind::tagged_union))};
    document.storage()
        .declarations.tagged_unions
        .export_specifier[document.storage().declarations.tagged_unions.index(replacement)] =
        document.storage().strings.intern("TAGGED_API");
    auto value{document.storage().declarations.tagged_union_alternatives.clone(
        document.storage().declarations.items(
            document.storage().declarations.tagged_unions.alternatives
                [document.storage().declarations.tagged_unions.index(replacement)])[0])};
    document.storage()
        .declarations.tagged_union_alternatives
        .type[document.storage().declarations.tagged_union_alternatives.index(value)] = [&] {
        auto row_0{document.storage().declarations.type_refs.clone(
            document.storage()
                .declarations.tagged_union_alternatives
                .type[document.storage().declarations.tagged_union_alternatives.index(value)])};
        document.storage()
            .declarations.type_refs.name[document.storage().declarations.type_refs.index(row_0)] =
            document.storage().strings.intern("std::uint64_t");
        return row_0;
    }();
    document.storage()
        .declarations.tagged_union_alternatives
        .count[document.storage().declarations.tagged_union_alternatives.index(value)] = 2;
    auto const small{document.storage().declarations.tagged_union_alternatives.append()};

    document.storage()
        .declarations.tagged_union_alternatives
        .name[document.storage().declarations.tagged_union_alternatives.index(small)] =
        document.storage().strings.intern("small");
    document.storage()
        .declarations.tagged_union_alternatives
        .type[document.storage().declarations.tagged_union_alternatives.index(small)] = [&] {
        auto const new_type_refs{document.storage().declarations.type_refs.append()};
        document.storage()
            .declarations.type_refs
            .name[document.storage().declarations.type_refs.index(new_type_refs)] =
            document.storage().strings.intern("std::uint8_t");
        return new_type_refs;
    }();
    document.storage()
        .declarations.tagged_union_alternatives
        .tag[document.storage().declarations.tagged_union_alternatives.index(small)] =
        document.storage().strings.intern("One");
    document.storage()
        .declarations.tagged_union_alternatives
        .count[document.storage().declarations.tagged_union_alternatives.index(small)] = 3;
    document.storage()
        .declarations.tagged_unions
        .alternatives[document.storage().declarations.tagged_unions.index(replacement)] =
        document.storage().declarations.range<lispb::codegen::TaggedUnionAlternativeId>(
            {small, value});

    auto applied{document.apply(document.replace_declaration(tagged, std::move(replacement)))};
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    auto preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    auto const& updated{preview->front().updated};
    auto const tagged_position{updated.find("(tagged-union ExistingTagged")};
    ASSERT_NE(tagged_position, std::string::npos);
    auto const small_position{updated.find("(alternative small ", tagged_position)};
    auto const declaration_comment{updated.find("; Keep the tagged union note.", tagged_position)};
    auto const value_comment{
        updated.find("; Keep the tagged value alternative note.", tagged_position)};
    auto const value_position{updated.find("(alternative value ", tagged_position)};
    ASSERT_NE(small_position, std::string::npos);
    ASSERT_NE(declaration_comment, std::string::npos);
    ASSERT_NE(value_comment, std::string::npos);
    ASSERT_NE(value_position, std::string::npos);
    EXPECT_LT(declaration_comment, small_position);
    EXPECT_LT(small_position, value_comment);
    EXPECT_LT(value_comment, value_position);
    EXPECT_NE(updated.find("(alternative small std::uint8_t :tag One :count 3)"),
              std::string::npos);
    EXPECT_NE(updated.find("(alternative value   std::uint64_t :tag Zero", tagged_position),
              std::string::npos);
    EXPECT_NE(updated.find(":count 2", value_position), std::string::npos);
    EXPECT_NE(updated.find("; tagged value trailing note"), std::string::npos);
    EXPECT_NE(updated.find(":discriminant   authored::Existing"), std::string::npos);
    EXPECT_NE(updated.find(":export-specifier TAGGED_API"), std::string::npos);

    ASSERT_TRUE(document.undo().value());
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    EXPECT_TRUE(preview->empty());
    ASSERT_TRUE(document.redo().value());

    auto deletion{document.storage().declarations.tagged_unions.clone(
        *document.declaration_handle(tagged, lispb::codegen::DeclarationKind::tagged_union))};
    document.storage()
        .declarations.tagged_unions
        .alternatives[document.storage().declarations.tagged_unions.index(deletion)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage()
                .declarations.tagged_unions
                .alternatives[document.storage().declarations.tagged_unions.index(deletion)])};
        auto rows{std::vector(original_items.begin(), original_items.end())};
        std::erase_if(rows, [&](auto id) {
            return document.storage().strings.view(
                       document.storage().declarations.tagged_union_alternatives.name
                           [document.storage().declarations.tagged_union_alternatives.index(id)]) ==
                   "value";
        });
        return document.storage().declarations.range(rows);
    }();
    applied = document.apply(document.replace_declaration(tagged, std::move(deletion)));
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    auto const deleted_tagged_position{
        preview->front().updated.find("(tagged-union ExistingTagged")};
    ASSERT_NE(deleted_tagged_position, std::string::npos);
    EXPECT_EQ(preview->front().updated.find("(alternative value ", deleted_tagged_position),
              std::string::npos);
    EXPECT_NE(
        preview->front().updated.find("; Keep the tagged union note.", deleted_tagged_position),
        std::string::npos);
    EXPECT_EQ(preview->front().updated.find("; Keep the tagged value alternative note.",
                                            deleted_tagged_position),
              std::string::npos);
    EXPECT_EQ(
        preview->front().updated.find("; tagged value trailing note", deleted_tagged_position),
        std::string::npos);
    EXPECT_NE(preview->front().updated.find("(alternative small ", deleted_tagged_position),
              std::string::npos);

    ASSERT_TRUE(document.undo().value());
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    auto const restored_tagged_position{
        preview->front().updated.find("(tagged-union ExistingTagged")};
    EXPECT_NE(preview->front().updated.find("(alternative value ", restored_tagged_position),
              std::string::npos);
    ASSERT_TRUE(document.redo().value());

    auto saved{document.save()};
    ASSERT_TRUE(saved.has_value()) << saved.error().message;
    auto reloaded{files.load()};
    auto const reloaded_tagged{
        declaration_id(reloaded, "authored_unions", "ExistingTagged", "authored")};
    auto const schema{reloaded.declaration_handle(reloaded_tagged,
                                                  lispb::codegen::DeclarationKind::tagged_union)};
    ASSERT_TRUE(schema.has_value());
    EXPECT_EQ(
        lispb::codegen::test_text(
            reloaded.storage().strings,
            reloaded.storage()
                .declarations.tagged_unions
                .export_specifier[reloaded.storage().declarations.tagged_unions.index(*schema)]),
        "TAGGED_API");
    ASSERT_EQ(reloaded.storage()
                  .declarations.tagged_unions
                  .alternatives[reloaded.storage().declarations.tagged_unions.index(*schema)]
                  .size(),
              1U);
    EXPECT_EQ(
        lispb::codegen::test_text(
            reloaded.storage().strings,
            reloaded.storage()
                .declarations.tagged_union_alternatives
                .name[reloaded.storage().declarations.tagged_union_alternatives.index(
                    reloaded.storage().declarations.items(
                        reloaded.storage().declarations.tagged_unions.alternatives
                            [reloaded.storage().declarations.tagged_unions.index(*schema)])[0])]),
        "small");
    EXPECT_EQ(
        lispb::codegen::test_text(
            reloaded.storage().strings,
            reloaded.storage()
                .declarations.tagged_union_alternatives
                .tag[reloaded.storage().declarations.tagged_union_alternatives.index(
                    reloaded.storage().declarations.items(
                        reloaded.storage().declarations.tagged_unions.alternatives
                            [reloaded.storage().declarations.tagged_unions.index(*schema)])[0])]),
        "One");
    EXPECT_EQ(reloaded.storage()
                  .declarations.tagged_union_alternatives
                  .count[reloaded.storage().declarations.tagged_union_alternatives.index(
                      reloaded.storage().declarations.items(
                          reloaded.storage().declarations.tagged_unions.alternatives
                              [reloaded.storage().declarations.tagged_unions.index(*schema)])[0])],
              3U);
}

TEST(EditableSchemaDocument, PreservesAggregateChildRowsDuringDirectRename) {
    TemporarySchema files;
    auto document{files.load()};
    auto const record{declaration_id(document, "authored_records", "ExistingRecord", "authored")};
    auto const raw{declaration_id(document, "authored_unions", "ExistingUnion", "authored")};
    auto const tagged{declaration_id(document, "authored_unions", "ExistingTagged", "authored")};

    auto record_replacement{document.storage().declarations.records.clone(
        *document.declaration_handle(record, lispb::codegen::DeclarationKind::record))};
    document.storage().declarations.records.members[document.storage().declarations.records.index(
        record_replacement)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage()
                .declarations.records
                .members[document.storage().declarations.records.index(record_replacement)])};
        auto rows_1{std::vector(original_items.begin(), original_items.end())};
        rows_1[0] = [&] {
            auto row_0{document.storage().declarations.record_members.clone(rows_1[0])};
            document.storage()
                .declarations.record_members
                .name[document.storage().declarations.record_members.index(row_0)] =
                document.storage().strings.intern("payload");
            return row_0;
        }();
        return document.storage().declarations.range(rows_1);
    }();
    auto applied{
        document.apply(document.replace_declaration(record, std::move(record_replacement)))};
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    auto raw_replacement{document.storage().declarations.unions.clone(
        *document.declaration_handle(raw, lispb::codegen::DeclarationKind::union_type))};
    document.storage()
        .declarations.unions
        .alternatives[document.storage().declarations.unions.index(raw_replacement)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage()
                .declarations.unions
                .alternatives[document.storage().declarations.unions.index(raw_replacement)])};
        auto rows_1{std::vector(original_items.begin(), original_items.end())};
        rows_1[0] = [&] {
            auto row_0{document.storage().declarations.union_alternatives.clone(rows_1[0])};
            document.storage()
                .declarations.union_alternatives
                .name[document.storage().declarations.union_alternatives.index(row_0)] =
                document.storage().strings.intern("payload");
            return row_0;
        }();
        return document.storage().declarations.range(rows_1);
    }();
    applied = document.apply(document.replace_declaration(raw, std::move(raw_replacement)));
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    auto tagged_replacement{document.storage().declarations.tagged_unions.clone(
        *document.declaration_handle(tagged, lispb::codegen::DeclarationKind::tagged_union))};
    document.storage()
        .declarations.tagged_unions
        .alternatives[document.storage().declarations.tagged_unions.index(tagged_replacement)] =
        [&] {
            auto const original_items{document.storage().declarations.items(
                document.storage().declarations.tagged_unions.alternatives
                    [document.storage().declarations.tagged_unions.index(tagged_replacement)])};
            auto rows_1{std::vector(original_items.begin(), original_items.end())};
            rows_1[0] = [&] {
                auto row_0{
                    document.storage().declarations.tagged_union_alternatives.clone(rows_1[0])};
                document.storage()
                    .declarations.tagged_union_alternatives
                    .name[document.storage().declarations.tagged_union_alternatives.index(row_0)] =
                    document.storage().strings.intern("payload");
                return row_0;
            }();
            return document.storage().declarations.range(rows_1);
        }();
    applied = document.apply(document.replace_declaration(tagged, std::move(tagged_replacement)));
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(*applied);

    auto preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    auto const& updated{preview->front().updated};

    auto const record_begin{updated.find("(record ExistingRecord")};
    auto const record_end{updated.find("(module authored_unions", record_begin)};
    ASSERT_NE(record_begin, std::string::npos);
    ASSERT_NE(record_end, std::string::npos);
    auto const record_source{updated.substr(record_begin, record_end - record_begin)};
    auto const record_comment{record_source.find("; Keep the value member note.")};
    auto const record_row{record_source.find("(member payload   std::uint32_t)")};
    ASSERT_NE(record_comment, std::string::npos);
    ASSERT_NE(record_row, std::string::npos) << record_source;
    EXPECT_LT(record_comment, record_row);
    EXPECT_NE(record_source.find("; value member trailing note"), std::string::npos);

    auto const raw_begin{updated.find("(union ExistingUnion")};
    auto const raw_end{updated.find("(tagged-union ExistingTagged", raw_begin)};
    ASSERT_NE(raw_begin, std::string::npos);
    ASSERT_NE(raw_end, std::string::npos);
    auto const raw_source{updated.substr(raw_begin, raw_end - raw_begin)};
    auto const raw_comment{raw_source.find("; Keep the value alternative note.")};
    auto const raw_row{raw_source.find("(alternative payload   std::uint32_t)")};
    ASSERT_NE(raw_comment, std::string::npos);
    ASSERT_NE(raw_row, std::string::npos) << raw_source;
    EXPECT_LT(raw_comment, raw_row);
    EXPECT_NE(raw_source.find("; value alternative trailing note"), std::string::npos);

    auto const tagged_begin{updated.find("(tagged-union ExistingTagged")};
    auto const tagged_end{updated.find("(module authored_soa", tagged_begin)};
    ASSERT_NE(tagged_begin, std::string::npos);
    ASSERT_NE(tagged_end, std::string::npos);
    auto const tagged_source{updated.substr(tagged_begin, tagged_end - tagged_begin)};
    auto const tagged_comment{tagged_source.find("; Keep the tagged value alternative note.")};
    auto const tagged_row{tagged_source.find("(alternative payload   std::uint32_t :tag Zero)")};
    ASSERT_NE(tagged_comment, std::string::npos);
    ASSERT_NE(tagged_row, std::string::npos) << tagged_source;
    EXPECT_LT(tagged_comment, tagged_row);
    EXPECT_NE(tagged_source.find("; tagged value trailing note"), std::string::npos);

    ASSERT_TRUE(document.undo().value());
    ASSERT_TRUE(document.undo().value());
    ASSERT_TRUE(document.undo().value());
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    EXPECT_TRUE(preview->empty());
    ASSERT_TRUE(document.redo().value());
    ASSERT_TRUE(document.redo().value());
    ASSERT_TRUE(document.redo().value());

    auto saved{document.save()};
    ASSERT_TRUE(saved.has_value()) << saved.error().message;
    auto reloaded{files.load()};
    auto const reloaded_record{
        declaration_id(reloaded, "authored_records", "ExistingRecord", "authored")};
    auto const reloaded_raw{
        declaration_id(reloaded, "authored_unions", "ExistingUnion", "authored")};
    auto const reloaded_tagged{
        declaration_id(reloaded, "authored_unions", "ExistingTagged", "authored")};
    auto const member{reloaded.storage().declarations.items(
        reloaded.storage()
            .declarations.records
            .members[reloaded.storage().declarations.records.index(*reloaded.declaration_handle(
                reloaded_record, lispb::codegen::DeclarationKind::record))])[0]};
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.record_members
                      .name[reloaded.storage().declarations.record_members.index(member)]),
              "payload");
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.type_refs.name[reloaded.storage().declarations.type_refs.index(
                          reloaded.storage().declarations.record_members.type
                              [reloaded.storage().declarations.record_members.index(member)])]),
              "std::uint32_t");
    EXPECT_FALSE(reloaded.storage()
                     .declarations.record_members
                     .count[reloaded.storage().declarations.record_members.index(member)]
                     .has_value());
    auto const raw_alternative{reloaded.storage().declarations.items(
        reloaded.storage()
            .declarations.unions
            .alternatives[reloaded.storage().declarations.unions.index(*reloaded.declaration_handle(
                reloaded_raw, lispb::codegen::DeclarationKind::union_type))])[0]};
    EXPECT_EQ(
        lispb::codegen::test_text(
            reloaded.storage().strings,
            reloaded.storage()
                .declarations.union_alternatives
                .name[reloaded.storage().declarations.union_alternatives.index(raw_alternative)]),
        "payload");
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.type_refs.name[reloaded.storage().declarations.type_refs.index(
                          reloaded.storage().declarations.union_alternatives.type
                              [reloaded.storage().declarations.union_alternatives.index(
                                  raw_alternative)])]),
              "std::uint32_t");
    EXPECT_FALSE(
        reloaded.storage()
            .declarations.union_alternatives
            .count[reloaded.storage().declarations.union_alternatives.index(raw_alternative)]
            .has_value());
    auto const tagged_alternative{reloaded.storage().declarations.items(
        reloaded.storage().declarations.tagged_unions.alternatives
            [reloaded.storage().declarations.tagged_unions.index(*reloaded.declaration_handle(
                reloaded_tagged, lispb::codegen::DeclarationKind::tagged_union))])[0]};
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.tagged_union_alternatives
                      .name[reloaded.storage().declarations.tagged_union_alternatives.index(
                          tagged_alternative)]),
              "payload");
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.type_refs.name[reloaded.storage().declarations.type_refs.index(
                          reloaded.storage().declarations.tagged_union_alternatives.type
                              [reloaded.storage().declarations.tagged_union_alternatives.index(
                                  tagged_alternative)])]),
              "std::uint32_t");
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.tagged_union_alternatives
                      .tag[reloaded.storage().declarations.tagged_union_alternatives.index(
                          tagged_alternative)]),
              "Zero");
    EXPECT_FALSE(reloaded.storage()
                     .declarations.tagged_union_alternatives
                     .count[reloaded.storage().declarations.tagged_union_alternatives.index(
                         tagged_alternative)]
                     .has_value());
}

TEST(EditableSchemaDocument, DeletesTaggedUnionThroughItsExactSourceRange) {
    TemporarySchema files;
    auto document{files.load()};
    auto const tagged{declaration_id(document, "authored_unions", "ExistingTagged", "authored")};
    auto const original_info{tagged};
    auto const original_info_source{
        document.declarations().source[document.declarations().index(original_info)]};
    ASSERT_TRUE(original_info_source.has_value());
    auto const source{*original_info_source};
    auto const original_text{
        std::string{document.storage().sources.text(document.source_span(source).file)}};
    auto expected_text{original_text};
    expected_text.erase(document.source_span(source).offset,
                        document.source_span(source).end_offset -
                            document.source_span(source).offset);

    ASSERT_TRUE(document.apply(document.delete_declaration(tagged)).value());
    auto preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    EXPECT_EQ(preview->front().updated, expected_text);
    EXPECT_NE(preview->front().updated.find("(union ExistingUnion"), std::string::npos);
    EXPECT_EQ(preview->front().updated.find("(tagged-union ExistingTagged"), std::string::npos);

    ASSERT_TRUE(document.undo().value());
    EXPECT_EQ(document.declarations().source[document.declarations().index(tagged)],
              original_info_source);
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    EXPECT_TRUE(preview->empty());
}

TEST(EditableSchemaDocument, RenamesEnumAndRepairsTaggedUnionDiscriminant) {
    TemporarySchema files;
    auto document{files.load()};
    auto const existing_enum{declaration_id(document, "authored_enums", "Existing", "authored")};
    auto const enum_module{
        document.declarations().module_index[document.declarations().index(existing_enum)]};
    auto const existing_tagged{
        declaration_id(document, "authored_unions", "ExistingTagged", "authored")};
    auto const union_module{
        document.declarations().module_index[document.declarations().index(existing_tagged)]};

    auto const enum_schema{document.storage().declarations.enums.append()};

    document.storage()
        .declarations.enums.name[document.storage().declarations.enums.index(enum_schema)] =
        document.storage().strings.intern("LocalKind");
    document.storage()
        .declarations.enums
        .underlying_type[document.storage().declarations.enums.index(enum_schema)] = [&] {
        auto const new_type_refs{document.storage().declarations.type_refs.append()};
        document.storage()
            .declarations.type_refs
            .name[document.storage().declarations.type_refs.index(new_type_refs)] =
            document.storage().strings.intern("std::uint8_t");
        document.storage()
            .declarations.type_refs
            .suffix[document.storage().declarations.type_refs.index(new_type_refs)] = {};
        document.storage()
            .declarations.type_refs
            .nested[document.storage().declarations.type_refs.index(new_type_refs)] = std::nullopt;
        return new_type_refs;
    }();
    auto const value{document.storage().declarations.enumerators.append()};

    document.storage()
        .declarations.enumerators.name[document.storage().declarations.enumerators.index(value)] =
        document.storage().strings.intern("Value");
    document.storage()
        .declarations.enums.values[document.storage().declarations.enums.index(enum_schema)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage()
                .declarations.enums
                .values[document.storage().declarations.enums.index(enum_schema)])};
        auto rows{std::vector(original_items.begin(), original_items.end())};
        rows.push_back(std::move(value));
        return document.storage().declarations.range(rows);
    }();
    auto const enumeration{document.allocate_declaration_id()};
    ASSERT_TRUE(document
                    .apply(document.create_declaration(
                        enumeration, enum_module, std::move(enum_schema), std::nullopt))
                    .has_value());

    auto const tagged_schema{document.storage().declarations.tagged_unions.append()};

    document.storage()
        .declarations.tagged_unions
        .name[document.storage().declarations.tagged_unions.index(tagged_schema)] =
        document.storage().strings.intern("LocalEvent");
    document.storage()
        .declarations.tagged_unions
        .discriminant[document.storage().declarations.tagged_unions.index(tagged_schema)] = [&] {
        auto const new_type_refs{document.storage().declarations.type_refs.append()};
        document.storage()
            .declarations.type_refs
            .name[document.storage().declarations.type_refs.index(new_type_refs)] =
            document.storage().strings.intern("authored::LocalKind");
        return new_type_refs;
    }();
    auto const alternative{document.storage().declarations.tagged_union_alternatives.append()};

    document.storage()
        .declarations.tagged_union_alternatives
        .name[document.storage().declarations.tagged_union_alternatives.index(alternative)] =
        document.storage().strings.intern("value");
    document.storage()
        .declarations.tagged_union_alternatives
        .type[document.storage().declarations.tagged_union_alternatives.index(alternative)] = [&] {
        auto const new_type_refs{document.storage().declarations.type_refs.append()};
        document.storage()
            .declarations.type_refs
            .name[document.storage().declarations.type_refs.index(new_type_refs)] =
            document.storage().strings.intern("std::uint32_t");
        return new_type_refs;
    }();
    document.storage()
        .declarations.tagged_union_alternatives
        .tag[document.storage().declarations.tagged_union_alternatives.index(alternative)] =
        document.storage().strings.intern("Value");
    document.storage()
        .declarations.tagged_unions
        .alternatives[document.storage().declarations.tagged_unions.index(tagged_schema)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage()
                .declarations.tagged_unions
                .alternatives[document.storage().declarations.tagged_unions.index(tagged_schema)])};
        auto rows{std::vector(original_items.begin(), original_items.end())};
        rows.push_back(std::move(alternative));
        return document.storage().declarations.range(rows);
    }();
    auto const tagged{document.allocate_declaration_id()};
    ASSERT_TRUE(document
                    .apply(document.create_declaration(
                        tagged, union_module, std::move(tagged_schema), std::nullopt))
                    .has_value());

    auto renamed{document.apply(document.rename_declaration(enumeration, "LocalKindRenamed"))};
    ASSERT_TRUE(renamed.has_value()) << renamed.error().message;
    EXPECT_EQ(lispb::codegen::test_text(
                  document.storage().strings,
                  document.storage()
                      .declarations.type_refs.name[document.storage().declarations.type_refs.index(
                          document.storage().declarations.tagged_unions.discriminant
                              [document.storage().declarations.tagged_unions.index(
                                  *document.declaration_handle(
                                      tagged, lispb::codegen::DeclarationKind::tagged_union))])]),
              "authored::LocalKindRenamed");
    auto const& resolved{tagged_union_type(document, tagged)};
    EXPECT_EQ(lispb::codegen::test_text(
                  document.storage().strings,
                  document.types().name(
                      document.types().occurrences().type[document.types().occurrences().index(
                          document.types().definitions().tagged_unions.discriminant
                              [document.types().definitions().tagged_unions.index(resolved)])])),
              "LocalKindRenamed");
    auto preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    EXPECT_NE(preview->front().updated.find(":discriminant authored::LocalKindRenamed"),
              std::string::npos);

    ASSERT_TRUE(document.undo().value());
    EXPECT_EQ(lispb::codegen::test_text(
                  document.storage().strings,
                  document.storage()
                      .declarations.type_refs.name[document.storage().declarations.type_refs.index(
                          document.storage().declarations.tagged_unions.discriminant
                              [document.storage().declarations.tagged_unions.index(
                                  *document.declaration_handle(
                                      tagged, lispb::codegen::DeclarationKind::tagged_union))])]),
              "authored::LocalKind");
}

TEST(EditableSchemaDocument, PreservesOwnedSourceWhenRenamingExistingDeclaration) {
    TemporarySchema files;
    auto document{files.load()};
    auto const scalar{declaration_id(document, "authored_scalars", "ExistingScalar", "authored")};
    auto const quantized{
        declaration_id(document, "authored_representations", "ExistingQ1", "authored")};
    auto const packed{declaration_id(document, "authored_packed", "ExistingPacked", "authored")};

    auto renamed{document.apply(document.rename_declaration(scalar, "ExistingScalarRenamed"))};
    ASSERT_TRUE(renamed.has_value()) << renamed.error().message;
    ASSERT_TRUE(*renamed);
    EXPECT_EQ(
        lispb::codegen::test_text(
            document.storage().strings,
            document.storage()
                .declarations.type_refs.name[document.storage().declarations.type_refs.index(
                    document.storage().declarations.linear_quantizeds.source
                        [document.storage().declarations.linear_quantizeds.index(
                            *document.declaration_handle(
                                quantized, lispb::codegen::DeclarationKind::linear_quantized))])]),
        "authored::ExistingScalarRenamed");
    ASSERT_TRUE(
        document.storage()
            .declarations.packed_fields
            .relationship[document.storage().declarations.packed_fields.index(
                document.storage().declarations.items(
                    document.storage().declarations.packed_values.segments
                        [document.storage().declarations.packed_values.index(
                            *document.declaration_handle(
                                packed, lispb::codegen::DeclarationKind::packed_value))])[1])]
            .has_value());
    EXPECT_EQ(
        lispb::codegen::test_text(
            document.storage().strings,
            document.storage()
                .declarations.type_refs.name[document.storage().declarations.type_refs.index(
                    document.storage().declarations.semantic_relations.target
                        [document.storage().declarations.semantic_relations.index(
                            (*document.storage().declarations.packed_fields.relationship
                                  [document.storage().declarations.packed_fields.index(
                                      document.storage().declarations.items(
                                          document.storage().declarations.packed_values.segments
                                              [document.storage().declarations.packed_values.index(
                                                  *document.declaration_handle(
                                                      packed,
                                                      lispb::codegen::DeclarationKind::
                                                          packed_value))])[1])]))])]),
        "authored::ExistingScalarRenamed");

    auto preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    auto const& updated{preview->front().updated};
    EXPECT_NE(updated.find("(integer-scalar ExistingScalarRenamed"), std::string::npos);
    EXPECT_EQ(updated.find("(integer-scalar ExistingScalar\n"), std::string::npos);
    EXPECT_NE(updated.find("; Keep the scalar domain note during ordinary edits."),
              std::string::npos);
    EXPECT_NE(updated.find(":minimum   0"), std::string::npos);
    EXPECT_NE(updated.find("(code Pending :value   2 :sentinel true)"), std::string::npos);
    EXPECT_NE(updated.find("; Keep the quantization note."), std::string::npos);
    EXPECT_NE(updated.find(":source   authored::ExistingScalarRenamed"), std::string::npos);
    EXPECT_NE(updated.find("; Keep the packed field note."), std::string::npos);
    EXPECT_NE(updated.find("(relation index_into authored::ExistingScalarRenamed)"),
              std::string::npos);

    ASSERT_TRUE(document.undo().value());
    preview = document.preview_source_updates();
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    EXPECT_TRUE(preview->empty());
    ASSERT_TRUE(document.redo().value());

    auto saved{document.save()};
    ASSERT_TRUE(saved.has_value()) << saved.error().message;
    auto reloaded{files.load()};
    auto const reloaded_scalar{
        declaration_id(reloaded, "authored_scalars", "ExistingScalarRenamed", "authored")};
    auto const reloaded_quantized{
        declaration_id(reloaded, "authored_representations", "ExistingQ1", "authored")};
    EXPECT_TRUE((reloaded.declarations().find(reloaded_scalar).has_value()));
    EXPECT_EQ(lispb::codegen::test_text(
                  reloaded.storage().strings,
                  reloaded.storage()
                      .declarations.type_refs.name[reloaded.storage().declarations.type_refs.index(
                          reloaded.storage().declarations.linear_quantizeds.source
                              [reloaded.storage().declarations.linear_quantizeds.index(
                                  *reloaded.declaration_handle(
                                      reloaded_quantized,
                                      lispb::codegen::DeclarationKind::linear_quantized))])]),
              "authored::ExistingScalarRenamed");
    auto const module_source{std::ranges::find_if(reloaded.source_files(), [&](auto const& source) {
        return reloaded.storage().sources.filesystem_path(source).filename() == "modules.lispb";
    })};
    ASSERT_NE(module_source, reloaded.source_files().end());
    EXPECT_NE(reloaded.storage()
                  .sources.text(*module_source)
                  .find("; Keep the scalar domain note during ordinary edits."),
              std::string::npos);
    EXPECT_NE(reloaded.storage()
                  .sources.text(*module_source)
                  .find("(code Pending :value   2 :sentinel true)"),
              std::string::npos);
    EXPECT_NE(reloaded.storage().sources.text(*module_source).find("; Keep the quantization note."),
              std::string::npos);
}

TEST(EditableSchemaDocument, AppliesResolvesAndInvertsTypedCommands) {
    auto document{fixture_document()};
    auto const id{declaration_id(document, "plain_enum_fixture", "EPlainFixture")};
    auto const original_info{id};
    auto const original_info_identity{
        document.declarations().identity[document.declarations().index(original_info)]};

    auto applied{document.apply(document.set_enumerator_display_name(id, "First", "First Value"))};

    ASSERT_TRUE(applied.has_value());
    EXPECT_TRUE(*applied);
    EXPECT_TRUE(document.dirty());
    EXPECT_TRUE(document.can_undo());
    EXPECT_FALSE(document.can_redo());
    EXPECT_EQ(document.revision(), 1);
    EXPECT_EQ(document.declarations().identity[document.declarations().index(id)],
              original_info_identity);
    auto const& edited{enum_type(document, id)};
    ASSERT_EQ(document.types()
                  .enum_domains()
                  .values(document.types()
                              .definitions()
                              .enums.domain[document.types().definitions().enums.index(edited)])
                  .size(),
              2);
    EXPECT_EQ(lispb::codegen::test_text(
                  document.storage().strings,
                  document.types()
                      .declarations()
                      .enumerators.display_name[document.types().declarations().enumerators.index(
                          document.types().enum_domains().values(
                              document.types().definitions().enums.domain
                                  [document.types().definitions().enums.index(edited)])[0])]),
              "First Value");

    document.mark_saved();
    EXPECT_FALSE(document.dirty());
    auto undo{document.undo()};
    ASSERT_TRUE(undo.has_value());
    EXPECT_TRUE(*undo);
    EXPECT_TRUE(document.dirty());
    EXPECT_FALSE(
        document.types()
            .declarations()
            .enumerators
            .display_name[document.types().declarations().enumerators.index(
                document.types().enum_domains().values(
                    document.types().definitions().enums.domain
                        [document.types().definitions().enums.index(enum_type(document, id))])[0])]
            .has_value());
    auto redo{document.redo()};
    ASSERT_TRUE(redo.has_value());
    EXPECT_TRUE(*redo);
    EXPECT_FALSE(document.dirty());
    EXPECT_EQ(lispb::codegen::test_text(
                  document.storage().strings,
                  document.types()
                      .declarations()
                      .enumerators.display_name[document.types().declarations().enumerators.index(
                          document.types().enum_domains().values(
                              document.types()
                                  .definitions()
                                  .enums.domain[document.types().definitions().enums.index(
                                      enum_type(document, id))])[0])]),
              "First Value");
    EXPECT_EQ(document.revision(), 3);
}

