TEST(EditableSchemaDocument, AllowsDeletionOfEntireModuleWithInternalDependencies) {
    TemporarySchema files;
    files.write_source("types.lispb", "");
    files.write_source("modules.lispb", R"((module related
  :header "Related.h"
  :namespace demo
  (record Foo (member value std::uint8_t))
  (record Bar (member foo demo::Foo)))

(module survivor
  :header "Survivor.h"
  :namespace demo
  (integer-scalar Keep :signed false :minimum 0 :maximum 1 :bit-width auto))
)");
    auto document{files.load()};
    auto const foo{declaration_id(document, "related", "Foo", "demo")};
    auto const bar{declaration_id(document, "related", "Bar", "demo")};
    auto const keep{declaration_id(document, "survivor", "Keep", "demo")};

    auto deleted{document.apply(document.delete_module(0))};
    ASSERT_TRUE(deleted.has_value()) << deleted.error().message;
    ASSERT_TRUE(*deleted);
    EXPECT_FALSE((document.declarations().find(foo).has_value()));
    EXPECT_FALSE((document.declarations().find(bar).has_value()));
    ASSERT_TRUE((document.declarations().find(keep).has_value()));
    EXPECT_EQ(document.declarations().module_index[document.declarations().index(keep)], 0U);
    EXPECT_FALSE(lispb::codegen::find_test_type(document.types(), "related", "Foo").has_value());
    EXPECT_FALSE(lispb::codegen::find_test_type(document.types(), "related", "Bar").has_value());
    EXPECT_TRUE(lispb::codegen::find_test_type(document.types(), "survivor", "Keep").has_value());
}

