    ASSERT_TRUE(renamed.has_value()) << renamed.error().message;
    ASSERT_TRUE(*renamed);
    EXPECT_EQ(
        lispb::codegen::test_text(
            document.storage().strings,
            document.declarations().identity[document.declarations().index(*declaration)].name),
        "RenamedScalar");
