    EXPECT_EQ(lispb::codegen::test_text(
                  document.storage().strings,
                  document.storage()
                      .declarations.type_refs.name[document.storage().declarations.type_refs.index(
                          document.storage().declarations.optional_presence_bits.source
                              [document.storage().declarations.optional_presence_bits.index(
                                  *document.declaration_handle(
                                      presence,
                                      lispb::codegen::DeclarationKind::optional_presence_bit))])]),
              "authored::ExistingScalar");
    ASSERT_TRUE(document.redo().value());
