TEST(EditableDocument, RejectsEditsThatMakeSemanticReferencesAmbiguous) {
    TemporarySchema files;
    for (auto const rename : {false, true}) {
        files.write_source("modules.lispb",
                           std::string{R"(
(module A :header "A.h" :namespace game
  (record Foo (member value int32))
  (record User (member foo Foo)))
(module B :header "B.h" :namespace game)
)"} + (rename ? R"(
(module C :header "C.h" :namespace game (record Bar (member value int32)))
(module D :header "D.h" (record OtherUser (member foo game::Foo)))
)"
              : R"(
(module C :header "C.h" :namespace game (record Foo (member value int32)))
)"));
        auto document{files.load()};
        auto const foo{declaration_id(document, "A", "Foo", "game")};
        auto const result{rename ? document.apply(document.rename_declaration(foo, "Bar"))
                                 : document.apply(document.move_declaration(foo, 1))};
        ASSERT_FALSE(result.has_value());
        EXPECT_EQ(
            lispb::codegen::test_text(
                document.storage().strings,
                document.declarations().identity[document.declarations().index(foo)].module_name),
            "A");
        EXPECT_EQ(lispb::codegen::test_text(
                      document.storage().strings,
                      document.declarations().identity[document.declarations().index(foo)].name),
                  "Foo");
        EXPECT_FALSE(document.can_undo());
        EXPECT_EQ(document.types().occurrences().type[document.types().occurrences().index(
                      document.types().definitions().record_members.semantic_type
                          [document.types().definitions().record_members.index(
                              document.types()
                                  .definitions()
                                  .records
                                  .members_of(record_type(
                                      document, declaration_id(document, "A", "User", "game")))
                                  .front())])],
                  *lispb::codegen::find_test_type(document.types(), "A", "Foo"));
    }
}

TEST(EditableDocument, GeneratedFamilyMoveAndRenamePreserveSpecializedUsers) {
    TemporarySchema files;
    files.write_source("modules.lispb", R"(
(module A :header "A.h" :source "A.cpp" :namespace game
  (layout Pairs :components (xs ys)
    (value-type float f :input-types (FPairsf))
    (value-type double d :input-types (FPairsf)))
  (layout Copies :components (xs ys)
    (value-type int32 i :input-types (FPairsf)))
  (table Lookup (row first) (column value FPairsf))
  (facade Access FPairsf target (method read FPairsd)))
(module B :header "B.h" :source "B.cpp" :namespace game)
)");
    auto document{files.load()};
    auto const layout{declaration_id(document, "A", "Pairs", "game")};
    auto check_bindings = [&](EditableSchemaDocument const& current,
                              std::string const& module,
                              std::string const& name) {
        auto const owner{declaration_id(current, module, name, "game")};
        auto const owned{current.types().types_for_declaration(*current.declaration_handle(owner))};
        ASSERT_EQ(owned.size(), 2U);
        auto uses{std::size_t{}};
        for (auto const use : current.types().type_uses()) {
            if (std::ranges::find(
                    owned,
                    current.types().occurrences().type[current.types().occurrences().index(
                        current.types().target(use))]) != owned.end()) {
                ++uses;
            }
        }
        EXPECT_EQ(uses, 6U);
    };
    check_bindings(document, "A", "Pairs");
    auto const moved{document.apply(document.move_declaration(layout, 1))};
    ASSERT_TRUE(moved.has_value()) << moved.error().message;
    check_bindings(document, "B", "Pairs");
    auto const renamed{document.apply(document.rename_declaration(layout, "Coordinates"))};
    ASSERT_TRUE(renamed.has_value()) << renamed.error().message;
    check_bindings(document, "B", "Coordinates");
    EXPECT_FALSE(document.apply(document.delete_declaration(layout)).has_value());
    EXPECT_FALSE(document.apply(document.delete_module(1)).has_value());
    ASSERT_TRUE(document.undo().value());
    ASSERT_TRUE(document.undo().value());
    EXPECT_EQ(
        lispb::codegen::test_text(
            document.storage().strings,
            document.declarations().identity[document.declarations().index(layout)].module_name),
        "A");
    check_bindings(document, "A", "Pairs");
    ASSERT_TRUE(document.redo().value());
    ASSERT_TRUE(document.redo().value());
    check_bindings(document, "B", "Coordinates");
    auto const saved{document.save()};
    ASSERT_TRUE(saved.has_value()) << saved.error().message;
    check_bindings(document, "B", "Coordinates");
    check_bindings(files.load(), "B", "Coordinates");
}

TEST(EditableDocument, SameNamespaceMoveKeepsOwnedReferencesLocalDespiteAmbiguousCppSpelling) {
    TemporarySchema files;
    files.write_source("modules.lispb", R"(
(module A :header "A.h" :source "A.cpp" :namespace game
  (layout Pairs :components (xs ys)
    (value-type double d :input-types (FPairsf))
    (value-type float f :input-types (FPairsf))))
(module B :header "B.h" :source "B.cpp" :namespace game
  (record Anchor (member value int32)))
(module C :header "C.h" :namespace game
  (record FPairsf (member value int32)))
)");
    auto document{files.load()};
    auto const layout{declaration_id(document, "A", "Pairs", "game")};
    auto check_binding = [&](EditableSchemaDocument const& current, std::string const& module) {
        auto const& graph{current.types()};
        auto const owner{current.declarations().identity[current.declarations().index(
            declaration_id(current, module, "Pairs", "game"))]};
        auto const target{lispb::codegen::find_test_type(graph, module, "FPairsf")};
        auto const sibling{lispb::codegen::find_test_type(graph, module, "FPairsd")};
        auto const other{lispb::codegen::find_test_type(graph, "C", "FPairsf")};
        ASSERT_TRUE(target.has_value());
        ASSERT_TRUE(sibling.has_value());
        ASSERT_TRUE(other.has_value());
        EXPECT_NE(*target, *other);
        EXPECT_NE(graph.identity(*target), owner);
        EXPECT_EQ(graph.source_declaration(*target),
                  *current.declaration_handle(*current.find_declaration(owner)));
        EXPECT_EQ(graph.origin(*target), TypeOrigin::declaration);
        EXPECT_EQ(graph
                      .types_for_declaration(
                          *current.declaration_handle(*current.find_declaration(owner)))
                      .size(),
                  2U);
        EXPECT_FALSE(
            graph
                .find_reference(
                    [&] {
                        auto const new_type_refs{current.storage().declarations.type_refs.append()};
                        current.storage()
                            .declarations.type_refs
                            .name[current.storage().declarations.type_refs.index(new_type_refs)] =
                            current.storage().strings.intern("game::FPairsf");
                        return new_type_refs;
                    }(),
                    graph.module(*target))
                .has_value());

        for (auto const id : {*target, *sibling}) {
            auto const& storage{graph.definition(id)};
            ASSERT_EQ(graph.definitions().homogeneous_storage.input_types_of(storage).size(), 1U);
            auto const input{
                graph.definitions().homogeneous_storage.input_types_of(storage).front()};
            EXPECT_EQ(graph.occurrences().type[graph.occurrences().index(input)], *target);
            EXPECT_EQ(current.manifest().types.cpp_types.spelling(
                          graph.occurrences().cpp_type[graph.occurrences().index(input)]),
                      "FPairsf");
        }
        auto const users{graph.users_of(*target)};
        ASSERT_EQ(users.size(), 1U);
        EXPECT_EQ(users.front(), *sibling);
        EXPECT_TRUE(graph.users_of(*other).empty());
        auto input_uses{std::size_t{}};
        for (auto const& use : graph.type_uses()) {
            if (graph.declaration(use) ==
                    *current.declaration_handle(*current.find_declaration(owner)) &&
                graph.role(use).part == lispb::codegen::TypeReferencePart::input &&
                graph.role(use).secondary_index == 0) {
                EXPECT_EQ(current.storage().strings.view(graph.module_name(*target)), module);
                EXPECT_EQ(graph.occurrences().type[graph.occurrences().index(graph.target(use))],
                          *target);
                ++input_uses;
            }
        }
        EXPECT_EQ(input_uses, 2U);
    };
    check_binding(document, "A");

    auto const moved{document.apply(document.move_declaration(layout, 1))};
    ASSERT_TRUE(moved.has_value()) << moved.error().message;
    ASSERT_TRUE(*moved);
    EXPECT_EQ(declaration_id(document, "B", "Pairs", "game"), layout);
    check_binding(document, "B");
    auto const undone{document.undo()};
    ASSERT_TRUE(undone.has_value()) << undone.error().message;
    ASSERT_TRUE(*undone);
    EXPECT_EQ(declaration_id(document, "A", "Pairs", "game"), layout);
    check_binding(document, "A");
    auto const redone{document.redo()};
    ASSERT_TRUE(redone.has_value()) << redone.error().message;
    ASSERT_TRUE(*redone);
    check_binding(document, "B");
    auto const preview{document.preview_source_updates()};
    ASSERT_TRUE(preview.has_value()) << preview.error().message;
    ASSERT_EQ(preview->size(), 1U);
    EXPECT_EQ(preview->front().updated.find("game::FPairsf"), std::string::npos);
    auto const saved{document.save()};
    ASSERT_TRUE(saved.has_value()) << saved.error().message;
    check_binding(document, "B");
    check_binding(files.load(), "B");
}

TEST(EditableDocument, SameNamespaceMovePreservesRegisteredAliases) {
    TemporarySchema files;
    files.write_source("types.lispb", R"((type foo :spelling "game::Foo" :header "A.h"))");
    files.write_source("modules.lispb", R"(
(module A :header "A.h" :namespace game
  (record Foo (member value int32))
  (record User (member first Foo) (member second @foo)))
(module B :header "B.h" :namespace game)
(module C :header "C.h" :namespace other)
)");
    auto document{files.load()};
    auto const foo{declaration_id(document, "A", "Foo", "game")};
    auto const user{declaration_id(document, "A", "User", "game")};
    auto const moved{document.apply(document.move_declaration(foo, 1))};
    ASSERT_TRUE(moved.has_value()) << moved.error().message;
    EXPECT_EQ(
        lispb::codegen::test_text(
            document.storage().strings,
            document.storage()
                .declarations.type_refs.name[document.storage().declarations.type_refs.index(
                    document.storage().declarations.record_members.type
                        [document.storage().declarations.record_members.index(
                            document.storage()
                                .declarations
                                .items(document.storage().declarations.records.members
                                           [document.storage().declarations.records.index(
                                               *document.declaration_handle(
                                                   user, lispb::codegen::DeclarationKind::record))])
                                .back())])]),
        "@foo");
    EXPECT_EQ(document.types().find_registered(document.types().strings().find("foo")),
              lispb::codegen::find_test_type(document.types(), "B", "Foo"));
    EXPECT_FALSE(document.apply(document.move_declaration(foo, 2)).has_value());
    EXPECT_FALSE(document.apply(document.rename_declaration(foo, "Renamed")).has_value());
    ASSERT_TRUE(document.undo().value());
    ASSERT_TRUE(document.redo().value());
    ASSERT_TRUE(document.save().has_value());
    auto const reloaded{files.load()};
    EXPECT_EQ(reloaded.types().find_registered(reloaded.types().strings().find("foo")),
              lispb::codegen::find_test_type(reloaded.types(), "B", "Foo"));
}

