TEST(EditableDocument, SameNamespaceMoveRejectsLocalSoaLinks) {
    TemporarySchema files;
    auto document{files.load()};
    auto const target{declaration_id(document, "authored_soa", "ExistingSoa", "authored")};
    auto const user{declaration_id(document, "authored_soa", "NestedFlags", "authored")};
    auto replacement{document.storage().declarations.soas.clone(
        *document.declaration_handle(user, lispb::codegen::DeclarationKind::soa))};
    document.storage()
        .declarations.soas.members[document.storage().declarations.soas.index(replacement)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage().declarations.soas.members[document.storage().declarations.soas.index(
                replacement)])};
        auto rows_1{std::vector(original_items.begin(), original_items.end())};
        rows_1.front() = [&] {
            auto row_0{document.storage().declarations.soa_members.clone(rows_1.front())};
            document.storage()
                .declarations.soa_members
                .kind[document.storage().declarations.soa_members.index(row_0)] =
                lispb::codegen::SoaMemberKind::nested;
            return row_0;
        }();
        return document.storage().declarations.range(rows_1);
    }();
    document.storage()
        .declarations.soas.members[document.storage().declarations.soas.index(replacement)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage().declarations.soas.members[document.storage().declarations.soas.index(
                replacement)])};
        auto rows_2{std::vector(original_items.begin(), original_items.end())};
        rows_2.front() = [&] {
            auto row_1{document.storage().declarations.soa_members.clone(rows_2.front())};
            document.storage()
                .declarations.soa_members
                .type[document.storage().declarations.soa_members.index(row_1)] = [&] {
                auto row_0{document.storage().declarations.type_refs.clone(
                    document.storage()
                        .declarations.soa_members
                        .type[document.storage().declarations.soa_members.index(row_1)])};
                document.storage()
                    .declarations.type_refs
                    .name[document.storage().declarations.type_refs.index(row_0)] =
                    document.storage().strings.intern("authored::ExistingSoa");
                return row_0;
            }();
            return row_1;
        }();
        return document.storage().declarations.range(rows_2);
    }();
    document.storage()
        .declarations.soas.members[document.storage().declarations.soas.index(replacement)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage().declarations.soas.members[document.storage().declarations.soas.index(
                replacement)])};
        auto rows_1{std::vector(original_items.begin(), original_items.end())};
        rows_1.front() = [&] {
            auto row_0{document.storage().declarations.soa_members.clone(rows_1.front())};
            document.storage()
                .declarations.soa_members
                .nested_schema[document.storage().declarations.soa_members.index(row_0)] =
                document.storage().strings.intern("ExistingSoa");
            return row_0;
        }();
        return document.storage().declarations.range(rows_1);
    }();
    document.storage()
        .declarations.soas.members[document.storage().declarations.soas.index(replacement)] = [&] {
        auto const original_items{document.storage().declarations.items(
            document.storage().declarations.soas.members[document.storage().declarations.soas.index(
                replacement)])};
        auto rows_1{std::vector(original_items.begin(), original_items.end())};
        rows_1.front() = [&] {
            auto row_0{document.storage().declarations.soa_members.clone(rows_1.front())};
            document.storage()
                .declarations.soa_members
                .fixed_schema[document.storage().declarations.soa_members.index(row_0)] =
                document.storage().strings.intern("ExistingSoa");
            return row_0;
        }();
        return document.storage().declarations.range(rows_1);
    }();
    ASSERT_TRUE(document.apply(document.replace_declaration(user, replacement)).has_value());
    auto const destination{document.declarations().module_index[document.declarations().index(
        declaration_id(document, "authored_records", "ExistingRecord", "authored"))]};
    auto const revision{document.revision()};
    for (auto const id : {target, user}) {
        auto const moved{document.apply(document.move_declaration(id, destination))};
        ASSERT_FALSE(moved.has_value());
        EXPECT_NE(moved.error().message.find("module-local nested/fixed"), std::string::npos);
        EXPECT_EQ(document.revision(), revision);
        EXPECT_EQ(
            lispb::codegen::test_text(
                document.storage().strings,
                document.declarations().identity[document.declarations().index(id)].module_name),
            "authored_soa");
    }
}

