TEST(EditableSchemaDocument, SavePrunesOldIdWhenDeclarationKindChanges) {
    TemporarySchema files;
    auto document{files.load()};
    auto const old_id{declaration_id(document, "authored_scalars", "OtherScalar", "authored")};
    auto const module_index{
        document.declarations().module_index[document.declarations().index(old_id)]};
    ASSERT_TRUE(document.apply(document.delete_declaration(old_id)).value());
    auto const new_id{document.allocate_declaration_id()};
    ASSERT_TRUE(
        document
            .apply(document.create_declaration(
                new_id,
                module_index,
                [&] {
                    auto const new_records{document.storage().declarations.records.append()};
                    document.storage()
                        .declarations.records
                        .name[document.storage().declarations.records.index(new_records)] =
                        document.storage().strings.intern("OtherScalar");
                    document.storage()
                        .declarations.records
                        .members[document.storage().declarations.records.index(new_records)] =
                        document.storage().declarations.range<lispb::codegen::RecordMemberId>({[&] {
                            auto const new_record_members{
                                document.storage().declarations.record_members.append()};
                            document.storage()
                                .declarations.record_members
                                .name[document.storage().declarations.record_members.index(
                                    new_record_members)] =
                                document.storage().strings.intern("value");
                            document.storage()
                                .declarations.record_members
                                .type[document.storage().declarations.record_members.index(
                                    new_record_members)] = [&] {
                                auto const new_type_refs{
                                    document.storage().declarations.type_refs.append()};
                                document.storage()
                                    .declarations.type_refs
                                    .name[document.storage().declarations.type_refs.index(
                                        new_type_refs)] =
                                    document.storage().strings.intern("std::uint8_t");
                                return new_type_refs;
                            }();
                            return new_record_members;
                        }()});
                    return new_records;
                }(),
                std::nullopt))
            .value());
    ASSERT_TRUE(document.save().has_value());
    EXPECT_FALSE((document.declarations().find(old_id).has_value()));
    EXPECT_TRUE(
        document.declaration_handle(new_id, lispb::codegen::DeclarationKind::record).has_value());
    EXPECT_FALSE(
        document.declaration_handle(new_id, lispb::codegen::DeclarationKind::integer_scalar)
            .has_value());
}

TEST(EditableSchemaDocument, SavePreservesCrLfAndVerifiesCleanDocuments) {
    TemporarySchema files;
    auto source{files.read_source("modules.lispb")};
    std::string crlf;
    for (auto const character : source) {
        if (character == '\n') {
            crlf += '\r';
        }
        crlf += character;
    }
    files.write_source("modules.lispb", crlf);
    auto document{files.load()};
    auto const scalar{declaration_id(document, "authored_scalars", "OtherScalar", "authored")};
    ASSERT_TRUE(document.apply(document.rename_declaration(scalar, "RenamedOtherScalar")).value());
    ASSERT_TRUE(document.save().has_value());
    auto const saved{files.read_source("modules.lispb")};
    for (std::size_t index{}; index < saved.size(); ++index) {
        if (saved[index] == '\n') {
            EXPECT_GT(index, 0U);
            EXPECT_EQ(saved[index - 1], '\r');
        }
    }
    EXPECT_EQ(lispb::codegen::test_text(
                  document.storage().strings,
                  document.declarations().identity[document.declarations().index(scalar)].name),
              "RenamedOtherScalar");
    files.write_source("modules.lispb", saved + "; external edit\r\n");
    auto const clean_save{document.save()};
    ASSERT_FALSE(clean_save.has_value());
    EXPECT_NE(clean_save.error().message.find("modules.lispb"), std::string::npos);
}

TEST(EditableSchemaDocument, SavePreservesLineEndingPolicyForGeneratedLinesAndNoOps) {
    for (auto const mode : {"lf", "crlf", "mixed"}) {
        SCOPED_TRACE(mode);
        TemporarySchema files;
        files.write_source("types.lispb", "");
        std::string source{"; Keep the first comment.\n; Keep the second comment.\n"
                           "(module scalars\n  :header \"Scalars.h\"\n"
                           "  (integer-scalar Value :signed false :minimum 0 :maximum 3))\n"};
        if (mode == std::string_view{"crlf"}) {
            std::string converted;
            for (auto const character : source) {
                if (character == '\n') {
                    converted += '\r';
                }
                converted += character;
            }
            source = std::move(converted);
        } else if (mode == std::string_view{"mixed"}) {
            source.insert(source.find('\n'), 1, '\r');
        }
        files.write_source("modules.lispb", source);
        auto document{files.load()};
        EXPECT_TRUE(document.preview_source_updates().value().empty());
        EXPECT_TRUE(document.save().value().empty());
        EXPECT_EQ(files.read_source("modules.lispb"), source);

        auto const existing{declaration_id(document, "scalars", "Value", "")};
        auto schema{
            document.storage().declarations.integer_scalars.clone(*document.declaration_handle(
                existing, lispb::codegen::DeclarationKind::integer_scalar))};
        document.storage()
            .declarations.integer_scalars
            .name[document.storage().declarations.integer_scalars.index(schema)] =
            document.storage().strings.intern("NewValue");
        auto const created{document.allocate_declaration_id()};
        ASSERT_TRUE(
            document.apply(document.create_declaration(created, 0, std::move(schema), std::nullopt))
                .value());
        auto const preview{document.preview_source_updates().value()};
        ASSERT_EQ(preview.size(), 1U);
        ASSERT_TRUE(document.save().has_value());
        auto const saved{files.read_source("modules.lispb")};
        EXPECT_EQ(saved, preview.front().updated);
        EXPECT_TRUE(saved.starts_with(source.substr(0, source.rfind(')'))));
        EXPECT_GT(std::ranges::count(saved, '\n'), std::ranges::count(source, '\n'));
        if (mode == std::string_view{"crlf"}) {
            char previous{};
            for (auto const character : saved) {
                if (character == '\n') {
                    EXPECT_EQ(previous, '\r');
                }
                previous = character;
            }
        } else {
            EXPECT_EQ(std::ranges::count(saved, '\r'), std::ranges::count(source, '\r'));
        }
        EXPECT_TRUE(document.preview_source_updates().value().empty());
        EXPECT_TRUE(document.save().value().empty());
        EXPECT_EQ(files.read_source("modules.lispb"), saved);
    }
}

TEST(EditableSchemaDocument, CompactApiRoundTripsAndRemovedViewFunctionsStayRemoved) {
    TemporarySchema files;
    auto document{files.load()};
    auto const id{declaration_id(document, "authored_soa", "ExistingSoa", "authored")};
    auto schema{document.storage().declarations.soas.clone(
        *document.declaration_handle(id, lispb::codegen::DeclarationKind::soa))};
    document.storage()
        .declarations.soas.single_allocation[document.storage().declarations.soas.index(schema)] =
        document.storage().strings.intern("CompactExisting");
    document.storage()
        .declarations.soas.using_declarations[document.storage().declarations.soas.index(schema)] =
        document.storage().declarations.range<lispb::StringId>(
            {document.storage().strings.add("Value = std::uint32_t")});
    document.storage()
        .declarations.soas.functions[document.storage().declarations.soas.index(schema)] =
        document.storage().declarations.range<lispb::codegen::FunctionSchemaId>({[&] {
            auto const new_functions{document.storage().declarations.functions.append()};
            document.storage()
                .declarations.functions
                .name[document.storage().declarations.functions.index(new_functions)] =
                document.storage().strings.intern("first");
            document.storage()
                .declarations.functions
                .return_type[document.storage().declarations.functions.index(new_functions)] = [&] {
                auto const new_type_refs{document.storage().declarations.type_refs.append()};
                document.storage()
                    .declarations.type_refs
                    .name[document.storage().declarations.type_refs.index(new_type_refs)] =
                    document.storage().strings.intern("std::uint32_t");
                return new_type_refs;
            }();
            document.storage()
                .declarations.functions
                .body_lines[document.storage().declarations.functions.index(new_functions)] =
                document.storage().declarations.range<lispb::StringId>(
                    {document.storage().strings.add("return $column(values)[0];")});
            document.storage()
                .declarations.functions
                .is_const[document.storage().declarations.functions.index(new_functions)] = true;
            return new_functions;
        }()});
    document.storage()
        .declarations.soas
        .const_view_functions[document.storage().declarations.soas.index(schema)] =
        document.storage().declarations.range<lispb::codegen::FunctionSchemaId>({[&] {
            auto const new_functions{document.storage().declarations.functions.append()};
            document.storage()
                .declarations.functions
                .name[document.storage().declarations.functions.index(new_functions)] =
                document.storage().strings.intern("read");
            document.storage()
                .declarations.functions
                .return_type[document.storage().declarations.functions.index(new_functions)] = [&] {
                auto const new_type_refs{document.storage().declarations.type_refs.append()};
                document.storage()
                    .declarations.type_refs
                    .name[document.storage().declarations.type_refs.index(new_type_refs)] =
                    document.storage().strings.intern("std::uint32_t");
                return new_type_refs;
            }();
            document.storage()
                .declarations.functions
                .body_lines[document.storage().declarations.functions.index(new_functions)] =
                document.storage().declarations.range<lispb::StringId>(
                    {document.storage().strings.add("return $column(values)[0];")});
            document.storage()
                .declarations.functions
                .is_const[document.storage().declarations.functions.index(new_functions)] = true;
            return new_functions;
        }()});
    document.storage()
        .declarations.soas
        .mutable_view_functions[document.storage().declarations.soas.index(schema)] =
        document.storage().declarations.range<lispb::codegen::FunctionSchemaId>({[&] {
            auto const new_functions{document.storage().declarations.functions.append()};
            document.storage()
                .declarations.functions
                .name[document.storage().declarations.functions.index(new_functions)] =
                document.storage().strings.intern("write");
            document.storage()
                .declarations.functions
                .return_type[document.storage().declarations.functions.index(new_functions)] = [&] {
                auto const new_type_refs{document.storage().declarations.type_refs.append()};
                document.storage()
                    .declarations.type_refs
                    .name[document.storage().declarations.type_refs.index(new_type_refs)] =
                    document.storage().strings.intern("void");
                return new_type_refs;
            }();
            document.storage()
                .declarations.functions
                .body_lines[document.storage().declarations.functions.index(new_functions)] =
                document.storage().declarations.range<lispb::StringId>(
                    {document.storage().strings.add("$column(values)[0] = 1;")});
            return new_functions;
        }()});
    auto applied{document.apply(document.replace_declaration(id, schema))};
    ASSERT_TRUE(applied.has_value()) << applied.error().message;
    ASSERT_TRUE(document.save().has_value());
    auto loaded{files.load()};
    auto const loaded_id{declaration_id(loaded, "authored_soa", "ExistingSoa", "authored")};
    auto replacement{loaded.storage().declarations.soas.clone(
        *loaded.declaration_handle(loaded_id, lispb::codegen::DeclarationKind::soa))};
    ASSERT_EQ(loaded.storage()
                  .declarations.soas
                  .const_view_functions[loaded.storage().declarations.soas.index(replacement)]
                  .size(),
              1U);
    ASSERT_EQ(loaded.storage()
                  .declarations.soas
                  .mutable_view_functions[loaded.storage().declarations.soas.index(replacement)]
                  .size(),
              1U);
    EXPECT_EQ(
        lispb::codegen::test_items(
            loaded.storage().declarations,
            loaded.storage()
                .declarations.functions.body_lines[loaded.storage().declarations.functions.index(
                    loaded.storage()
                        .declarations
                        .items(loaded.storage().declarations.soas.functions
                                   [loaded.storage().declarations.soas.index(replacement)])
                        .front())]),
        lispb::codegen::test_items(
            document.storage().declarations,
            document.storage()
                .declarations.functions.body_lines[document.storage().declarations.functions.index(
                    document.storage()
                        .declarations
                        .items(document.storage().declarations.soas.functions
                                   [document.storage().declarations.soas.index(schema)])
                        .front())]));
    loaded.storage()
        .declarations.soas
        .const_view_functions[loaded.storage().declarations.soas.index(replacement)] = {};
    loaded.storage()
        .declarations.soas
        .mutable_view_functions[loaded.storage().declarations.soas.index(replacement)] = {};
    ASSERT_TRUE(loaded.apply(loaded.replace_declaration(loaded_id, replacement)).has_value());
    ASSERT_TRUE(loaded.save().has_value());
    auto cleared{files.load()};
    auto const cleared_id{declaration_id(cleared, "authored_soa", "ExistingSoa", "authored")};
    EXPECT_TRUE(
        cleared.storage()
            .declarations.soas
            .const_view_functions[cleared.storage().declarations.soas.index(
                *cleared.declaration_handle(cleared_id, lispb::codegen::DeclarationKind::soa))]
            .empty());
    EXPECT_TRUE(
        cleared.storage()
            .declarations.soas
            .mutable_view_functions[cleared.storage().declarations.soas.index(
                *cleared.declaration_handle(cleared_id, lispb::codegen::DeclarationKind::soa))]
            .empty());
}

